/**
 * What an upload key is allowed to look like.
 *
 * One place, because three different pieces of code have to agree about it and
 * they drifted: the serving route rejected the `message/` prefix that the chat
 * uploader had started producing, so every photo and clip sent in a
 * conversation was a 404 — the whole feature dead, with a green test suite,
 * because nothing ever fetched an uploaded URL back.
 *
 * Keys are generated by `putUpload` and never taken from a request, so a real
 * one always has this exact shape. Checking it before touching the filesystem
 * keeps anything interesting from reaching it, and checking it before trusting
 * a client-supplied reference keeps one person's message from pointing at
 * another person's file.
 */

/** Stills, allowed everywhere. */
const IMAGE_EXT = ["png", "jpg", "webp", "gif"] as const;

/** Clips, allowed only in chat — see `putUpload`. */
const VIDEO_EXT = ["mp4", "mov", "webm"] as const;

const IMAGE_KINDS = ["cover", "avatar", "proof", "message"] as const;

/**
 * An ID check's photos. No GIF: an ID is a photo, and `putUpload` refuses
 * one under `kyc`. The selfie clip uses the chat's video types.
 */
const KYC_IMAGE_EXT = ["png", "jpg", "webp"] as const;

const KYC_IMAGE = new RegExp(
  `^kyc/[0-9a-f]{32}\\.(?:${KYC_IMAGE_EXT.join("|")})$`,
);
const KYC_VIDEO = new RegExp(`^kyc/[0-9a-f]{32}\\.(?:${VIDEO_EXT.join("|")})$`);

const SERVABLE = new RegExp(
  `^(?:(?:${IMAGE_KINDS.join("|")})/[0-9a-f]{32}\\.(?:${IMAGE_EXT.join("|")})` +
    `|message/[0-9a-f]{32}\\.(?:${VIDEO_EXT.join("|")}))$`,
);

/** Whether this key may be read off disk and served. */
export function isServableKey(key: string): boolean {
  return SERVABLE.test(key) || isKycKey(key);
}

/**
 * Listing artwork and profile photos: the same for everybody who asks, so
 * public (`canReadUpload`), and the only uploads any shared cache or the
 * image optimiser may hold.
 */
const PUBLIC = new RegExp(
  `^(?:cover|avatar)/[0-9a-f]{32}\\.(?:${IMAGE_EXT.join("|")})$`,
);

export function isPublicKey(key: string): boolean {
  return PUBLIC.test(key);
}

/**
 * An ID check's file: a photo of the ID or the selfie video.
 *
 * Private, like nothing else here: only the member who sent it and the staff
 * who review ID checks may read one (`canReadUpload`).
 */
export function isKycKey(key: string): boolean {
  return KYC_IMAGE.test(key) || KYC_VIDEO.test(key);
}

/** A photo of an ID, as `putUpload` stores it under `kyc`. */
export function isKycImageKey(key: string): boolean {
  return KYC_IMAGE.test(key);
}

/** The selfie video of an ID check. */
export function isKycVideoKey(key: string): boolean {
  return KYC_VIDEO.test(key);
}

/**
 * Whether this key may be attached to a chat message.
 *
 * Narrower than `isServableKey` on purpose. Cover, avatar and proof URLs are
 * public — they are rendered on every listing card — so accepting one here let
 * somebody attach a competitor's proof screenshot to their own thread and have
 * the retention sweep delete it forty-eight hours later.
 */
const CHAT_ATTACHMENT = new RegExp(
  `^message/[0-9a-f]{32}\\.(?:${[...IMAGE_EXT, ...VIDEO_EXT].join("|")})$`,
);

export function isChatAttachmentKey(key: string): boolean {
  return CHAT_ATTACHMENT.test(key);
}

/** Whether a key names a clip, decided by the extension the key was given. */
export function keyIsVideo(key: string): boolean {
  return VIDEO_EXT.some((ext) => key.endsWith(`.${ext}`));
}

/** The public path a key is served at. */
export function urlForKey(key: string): string {
  return `/uploads/${key}`;
}

/**
 * The key a stored URL refers to, or null if it is not one of ours.
 *
 * Returns null rather than a best guess so a caller that is about to delete
 * something has to handle the case where the URL points somewhere else.
 */
export function keyFromUrl(url: string): string | null {
  if (!url.startsWith("/uploads/")) return null;
  const key = url.slice("/uploads/".length);
  return isServableKey(key) ? key : null;
}

/**
 * How long, and by whom, a served file may be kept: the uploads route's
 * caching headers. Here rather than in the route, which may export only its
 * HTTP methods.
 *
 * Listing artwork — a cover or an account's picture — is on every card and
 * the same for everybody, so any cache may keep it for a year: a file never
 * changes under its key. That is what lets the image optimiser and a CDN
 * hold it, and what spares a phone downloading the same cover on every
 * page.
 *
 * Everything else is private: permission-gated bytes that a shared cache
 * would serve one person's screenshot to the next requester. The browser's
 * own cache may still hold them, keyed by the cookie that was let in —
 * except an ID check's, which is not written to the disk of whatever
 * computer staff reviewed it on.
 */
const TYPES: Record<string, string> = {
  png: "image/png",
  jpg: "image/jpeg",
  webp: "image/webp",
  gif: "image/gif",
  mp4: "video/mp4",
  mov: "video/quicktime",
  webm: "video/webm",
};

/**
 * A stored file's type, from its key. `putUpload` named the file from its
 * own bytes, so the extension is as good as reading them again — which a
 * file on ImageKit, passed on as it streams, cannot be.
 */
export function contentTypeOf(key: string): string {
  return (
    TYPES[key.slice(key.lastIndexOf(".") + 1)] ?? "application/octet-stream"
  );
}

export function cachingFor(key: string): Record<string, string> {
  if (isPublicKey(key)) {
    return { "Cache-Control": "public, max-age=31536000, immutable" };
  }
  return {
    "Cache-Control": isKycKey(key)
      ? "private, no-store"
      : "private, max-age=31536000, immutable",
    Vary: "Cookie",
  };
}
